// Write implements io.Writer.
func (fd *Windows_FD) Write(buf []byte) (int, error) {
	if fd.kind == windows_kindFile {
		if err := fd.readWriteLock(); err != nil {
			return 0, err
		}
		defer fd.readWriteUnlock()
	} else {
		if err := fd.writeLock(); err != nil {
			return 0, err
		}
		defer fd.writeUnlock()
	}

	var ntotal int
	for {
		max := len(buf)
		if max-ntotal > windows_maxRW {
			max = ntotal + windows_maxRW
		}
		b := buf[ntotal:max]
		var n int
		var err error
		switch fd.kind {
		case windows_kindConsole:
			n, err = fd.writeConsole(b)
		case windows_kindPipe, windows_kindFile:
			n, err = fd.execIO('w', func(o *windows_operation) (qty uint32, err error) {
				err = syscall.Windows_WriteFile(fd.Sysfd, b, &qty, fd.overlapped(o))
				return qty, err
			}, windows_pinPtrsFromBuf(b)...)
			fd.addOffset(n)
		case windows_kindNet:
			if race.Enabled {
				race.ReleaseMerge(unsafe.Pointer(&windows_ioSync))
			}
			n, err = fd.execIO('w', func(o *windows_operation) (qty uint32, err error) {
				err = syscall.Windows_WSASend(fd.Sysfd, windows_newWsaBuf(b), 1, &qty, 0, &o.o, nil)
				return qty, err
			}, windows_pinPtrsFromBuf(b)...)
		}
		ntotal += n
		if ntotal == len(buf) || err != nil {
			return ntotal, err
		}
		if n == 0 {
			return ntotal, io.ErrUnexpectedEOF
		}
	}
}

// writeConsole writes len(b) bytes to the console File.
// It returns the number of bytes written and an error, if any.
func (fd *Windows_FD) writeConsole(b []byte) (int, error) {
	n := len(b)
	runes := make([]rune, 0, 256)
	if len(fd.lastbits) > 0 {
		b = append(fd.lastbits, b...)
		fd.lastbits = nil

	}
	for len(b) >= utf8.UTFMax || utf8.FullRune(b) {
		r, l := utf8.DecodeRune(b)
		runes = append(runes, r)
		b = b[l:]
	}
	if len(b) > 0 {
		fd.lastbits = make([]byte, len(b))
		copy(fd.lastbits, b)
	}
	// syscall.WriteConsole seems to fail, if given large buffer.
	// So limit the buffer to 16000 characters. This number was
	// discovered by experimenting with syscall.WriteConsole.
	const maxWrite = 16000
	for len(runes) > 0 {
		m := len(runes)
		if m > maxWrite {
			m = maxWrite
		}
		chunk := runes[:m]
		runes = runes[m:]
		uint16s := utf16.Encode(chunk)
		for len(uint16s) > 0 {
			var written uint32
			err := syscall.Windows_WriteConsole(fd.Sysfd, &uint16s[0], uint32(len(uint16s)), &written, nil)
			if err != nil {
				return 0, err
			}
			uint16s = uint16s[written:]
		}
	}
	return n, nil
}

// Pwrite emulates the Unix pwrite system call.
func (fd *Windows_FD) Pwrite(buf []byte, off int64) (int, error) {
	if fd.kind == windows_kindPipe {
		// Pwrite does not work with pipes
		return 0, syscall.Windows_ESPIPE
	}

	if err := fd.readWriteLock(); err != nil {
		return 0, err
	}
	defer fd.readWriteUnlock()

	var ntotal int
	for {
		max := len(buf)
		if max-ntotal > windows_maxRW {
			max = ntotal + windows_maxRW
		}
		b := buf[ntotal:max]
		n, err := fd.execIO('w', func(o *windows_operation) (qty uint32, err error) {
			// Overlapped handles don't have the file pointer updated
			// when performing I/O operations, so there is no need to
			// call Seek to reset the file pointer.
			// Also, some overlapped file handles don't support seeking.
			// See https://go.dev/issues/74951.
			if fd.isBlocking {
				curoffset, err := syscall.Windows_Seek(fd.Sysfd, 0, io.SeekCurrent)
				if err != nil {
					return 0, err
				}
				defer syscall.Windows_Seek(fd.Sysfd, curoffset, io.SeekStart)
			}
			o.setOffset(off + int64(ntotal))

			err = syscall.Windows_WriteFile(fd.Sysfd, b, &qty, &o.o)
			return qty, err
		}, windows_pinPtrsFromBuf(b)...)
		if n > 0 {
			ntotal += n
		}
		if ntotal == len(buf) || err != nil {
			return ntotal, err
		}
		if n == 0 {
			return ntotal, io.ErrUnexpectedEOF
		}
	}
}

// Writev emulates the Unix writev system call.
func (fd *Windows_FD) Writev(buf *[][]byte) (int64, error) {
	if len(*buf) == 0 {
		return 0, nil
	}
	if err := fd.writeLock(); err != nil {
		return 0, err
	}
	defer fd.writeUnlock()
	if race.Enabled {
		race.ReleaseMerge(unsafe.Pointer(&windows_ioSync))
	}
	bufs := windows_newWSABufs(buf)
	defer windows_freeWSABufs(bufs)
	n, err := fd.execIO('w', func(o *windows_operation) (qty uint32, err error) {
		err = syscall.Windows_WSASend(fd.Sysfd, &(*bufs)[0], uint32(len(*bufs)), &qty, 0, &o.o, nil)
		return qty, err
	})
	TestHookDidWritev(n)
	consume(buf, int64(n))
	return int64(n), err
}

// WriteTo wraps the sendto network call.
func (fd *Windows_FD) WriteTo(buf []byte, sa syscall.Windows_Sockaddr) (int, error) {
	if err := fd.writeLock(); err != nil {
		return 0, err
	}
	defer fd.writeUnlock()

	if len(buf) == 0 {
		// handle zero-byte payload
		n, err := fd.execIO('w', func(o *windows_operation) (qty uint32, err error) {
			err = syscall.Windows_WSASendto(fd.Sysfd, &syscall.Windows_WSABuf{}, 1, &qty, 0, sa, &o.o, nil)
			return qty, err
		})
		return n, err
	}

	ntotal := 0
	for len(buf) > 0 {
		b := buf
		if len(b) > windows_maxRW {
			b = b[:windows_maxRW]
		}
		n, err := fd.execIO('w', func(o *windows_operation) (qty uint32, err error) {
			err = syscall.Windows_WSASendto(fd.Sysfd, windows_newWsaBuf(b), 1, &qty, 0, sa, &o.o, nil)
			return qty, err
		}, unsafe.SliceData(b))
		ntotal += int(n)
		if err != nil {
			return ntotal, err
		}
		buf = buf[n:]
	}
	return ntotal, nil
}

