// RawRead invokes the user-defined function f for a read operation.
func (fd *Windows_FD) RawRead(f func(uintptr) bool) error {
	if err := fd.readLock(); err != nil {
		return err
	}
	defer fd.readUnlock()
	for {
		if f(uintptr(fd.Sysfd)) {
			return nil
		}

		// Use a zero-byte read as a way to get notified when this
		// socket is readable. h/t https://stackoverflow.com/a/42019668/332798
		_, err := fd.execIO('r', func(o *windows_operation) (qty uint32, err error) {
			var flags uint32
			if !fd.IsStream {
				flags |= windows.Windows_MSG_PEEK
			}
			err = syscall.Windows_WSARecv(fd.Sysfd, &syscall.Windows_WSABuf{}, 1, &qty, &flags, &o.o, nil)
			return qty, err
		})
		if err == windows.Windows_WSAEMSGSIZE {
			// expected with a 0-byte peek, ignore.
		} else if err != nil {
			return err
		}
	}
}

// RawWrite invokes the user-defined function f for a write operation.
func (fd *Windows_FD) RawWrite(f func(uintptr) bool) error {
	if err := fd.writeLock(); err != nil {
		return err
	}
	defer fd.writeUnlock()

	if f(uintptr(fd.Sysfd)) {
		return nil
	}

	// TODO(tmm1): find a way to detect socket writability
	return syscall.Windows_EWINDOWS
}

func windows_sockaddrInet4ToRaw(rsa *syscall.Windows_RawSockaddrAny, sa *syscall.Windows_SockaddrInet4) int32 {
	*rsa = syscall.Windows_RawSockaddrAny{}
	raw := (*syscall.Windows_RawSockaddrInet4)(unsafe.Pointer(rsa))
	raw.Family = syscall.Windows_AF_INET
	p := (*[2]byte)(unsafe.Pointer(&raw.Port))
	p[0] = byte(sa.Port >> 8)
	p[1] = byte(sa.Port)
	raw.Addr = sa.Addr
	return int32(unsafe.Sizeof(*raw))
}

func windows_sockaddrInet6ToRaw(rsa *syscall.Windows_RawSockaddrAny, sa *syscall.Windows_SockaddrInet6) int32 {
	*rsa = syscall.Windows_RawSockaddrAny{}
	raw := (*syscall.Windows_RawSockaddrInet6)(unsafe.Pointer(rsa))
	raw.Family = syscall.Windows_AF_INET6
	p := (*[2]byte)(unsafe.Pointer(&raw.Port))
	p[0] = byte(sa.Port >> 8)
	p[1] = byte(sa.Port)
	raw.Scope_id = sa.ZoneId
	raw.Addr = sa.Addr
	return int32(unsafe.Sizeof(*raw))
}

func windows_rawToSockaddrInet4(rsa *syscall.Windows_RawSockaddrAny, sa *syscall.Windows_SockaddrInet4) {
	pp := (*syscall.Windows_RawSockaddrInet4)(unsafe.Pointer(rsa))
	p := (*[2]byte)(unsafe.Pointer(&pp.Port))
	sa.Port = int(p[0])<<8 + int(p[1])
	sa.Addr = pp.Addr
}

func windows_rawToSockaddrInet6(rsa *syscall.Windows_RawSockaddrAny, sa *syscall.Windows_SockaddrInet6) {
	pp := (*syscall.Windows_RawSockaddrInet6)(unsafe.Pointer(rsa))
	p := (*[2]byte)(unsafe.Pointer(&pp.Port))
	sa.Port = int(p[0])<<8 + int(p[1])
	sa.ZoneId = pp.Scope_id
	sa.Addr = pp.Addr
}

func windows_sockaddrToRaw(rsa *syscall.Windows_RawSockaddrAny, sa syscall.Windows_Sockaddr) (int32, error) {
	switch sa := sa.(type) {
	case *syscall.Windows_SockaddrInet4:
		sz := windows_sockaddrInet4ToRaw(rsa, sa)
		return sz, nil
	case *syscall.Windows_SockaddrInet6:
		sz := windows_sockaddrInet6ToRaw(rsa, sa)
		return sz, nil
	default:
		return 0, syscall.Windows_EWINDOWS
	}
}

// ReadMsg wraps the WSARecvMsg network call.
func (fd *Windows_FD) ReadMsg(p []byte, oob []byte, flags int) (int, int, int, syscall.Windows_Sockaddr, error) {
	if err := fd.readLock(); err != nil {
		return 0, 0, 0, nil, err
	}
	defer fd.readUnlock()

	if len(p) > windows_maxRW {
		p = p[:windows_maxRW]
	}

	rsa := windows_newWSARsa()
	defer windows_wsaRsaPool.Put(rsa)
	msg := windows_newWSAMsg(p, oob, flags, rsa)
	defer windows_freeWSAMsg(msg)
	n, err := fd.execIO('r', func(o *windows_operation) (qty uint32, err error) {
		err = windows.Windows_WSARecvMsg(fd.Sysfd, msg, &qty, &o.o, nil)
		return qty, err
	}, rsa, msg)
	err = fd.eofError(n, err)
	var sa syscall.Windows_Sockaddr
	if err == nil {
		sa, err = msg.Name.Sockaddr()
	}
	return n, int(msg.Control.Len), int(msg.Flags), sa, err
}

