// WriteMsg wraps the WSASendMsg network call.
func (fd *Windows_FD) WriteMsg(p []byte, oob []byte, sa syscall.Windows_Sockaddr) (int, int, error) {
	if len(p) > windows_maxRW {
		return 0, 0, errors.New("packet is too large (only 1GB is allowed)")
	}

	if err := fd.writeLock(); err != nil {
		return 0, 0, err
	}
	defer fd.writeUnlock()

	var rsa *windows_wsaRsa
	if sa != nil {
		rsa = windows_newWSARsa()
		defer windows_wsaRsaPool.Put(rsa)
		var err error
		rsa.namelen, err = windows_sockaddrToRaw(&rsa.name, sa)
		if err != nil {
			return 0, 0, err
		}
	}
	msg := windows_newWSAMsg(p, oob, 0, rsa)
	defer windows_freeWSAMsg(msg)
	n, err := fd.execIO('w', func(o *windows_operation) (qty uint32, err error) {
		err = windows.Windows_WSASendMsg(fd.Sysfd, msg, 0, nil, &o.o, nil)
		return qty, err
	}, rsa, msg)
	return n, int(msg.Control.Len), err
}

