func Windows_DupCloseOnExec(fd int) (int, string, error) {
	proc, err := syscall.Windows_GetCurrentProcess()
	if err != nil {
		return 0, "GetCurrentProcess", err
	}

	var nfd syscall.Windows_Handle
	const inherit = false // analogous to CLOEXEC
	if err := syscall.Windows_DuplicateHandle(proc, syscall.Windows_Handle(fd), proc, &nfd, 0, inherit, syscall.Windows_DUPLICATE_SAME_ACCESS); err != nil {
		return 0, "DuplicateHandle", err
	}
	return int(nfd), "", nil
}
